		templ_7745c5c3_Buffer, templ_7745c5c3_IsBuffer := templruntime.GetBuffer(templ_7745c5c3_W)
		if !templ_7745c5c3_IsBuffer {
			defer func() {
				templ_7745c5c3_BufErr := templruntime.ReleaseBuffer(templ_7745c5c3_Buffer)
				if templ_7745c5c3_Err == nil {
					templ_7745c5c3_Err = templ_7745c5c3_BufErr
				}
			}()
		}
		ctx = templ.InitializeContext(ctx)
		templ_7745c5c3_Var18 := templ.GetChildren(ctx)
		if templ_7745c5c3_Var18 == nil {
			templ_7745c5c3_Var18 = templ.NopComponent
		}
		ctx = templ.ClearChildren(ctx)
		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 21, "<script>\n/* ============================================================\n   DATA LAYER\n   Real VPS ingest endpoint can be wired here:\n     const res = await fetch('https://your-vps.example/api/stats');\n     return await res.json();\n   Returns null for now so live readout displays N/A.\n   ============================================================ */\nasync function fetchStats(){\n  return null;\n}\n\nfunction crateIcon(accent){\n  return `\n  <svg width=\"46\" height=\"40\" viewBox=\"0 0 46 40\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect x=\"2\" y=\"10\" width=\"42\" height=\"26\" rx=\"1.5\" fill=\"#1c2126\" stroke=\"${accent}\" stroke-width=\"1.5\"/>\n    <path d=\"M2 18H44\" stroke=\"${accent}\" stroke-width=\"1.2\" opacity=\"0.55\"/>\n    <path d=\"M17 10L23 2L29 10\" stroke=\"${accent}\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n    <circle cx=\"23\" cy=\"24\" r=\"4.5\" fill=\"none\" stroke=\"${accent}\" stroke-width=\"1.5\"/>\n    <rect x=\"21.2\" y=\"23\" width=\"3.6\" height=\"4\" rx=\"0.6\" fill=\"${accent}\"/>\n  </svg>`;\n}\n\nfunction fmt(n){ return n != null ? n.toLocaleString('en-US') : 'N/A'; }\n\nfunction render(data){\n  if (!data) {\n    document.getElementById('stat-total').textContent = 'N/A';\n    document.getElementById('stat-active').textContent = 'N/A';\n    document.getElementById('stat-done').textContent = 'N/A';\n    document.getElementById('bar-active').style.width = '0%';\n    document.getElementById('bar-done').style.width = '0%';\n    document.getElementById('vault-meta').textContent = 'N/A — awaiting ingest';\n    document.getElementById('rarity-meta').textContent = 'N/A — awaiting ingest';\n    return;\n  }\n\n  // When live data is returned:\n  document.getElementById('stat-total').textContent = data.accounts?.total != null ? fmt(data.accounts.total) : 'N/A';\n  document.getElementById('stat-active').textContent = data.accounts?.active != null ? fmt(data.accounts.active) : 'N/A';\n  document.getElementById('stat-done').textContent = data.accounts?.completed != null ? fmt(data.accounts.completed) : 'N/A';\n  \n  if (data.accounts?.total) {\n    document.getElementById('bar-active').style.width = ((data.accounts.active || 0) / data.accounts.total * 100).toFixed(0) + '%';\n    document.getElementById('bar-done').style.width = ((data.accounts.completed || 0) / data.accounts.total * 100).toFixed(0) + '%';\n  } else {\n    document.getElementById('bar-active').style.width = '0%';\n    document.getElementById('bar-done').style.width = '0%';\n  }\n\n  // Case Vault\n  const vaultEl = document.getElementById('vault-grid');\n  if (data.cases && data.cases.length > 0) {\n    const totalCases = data.cases.reduce((a,c)=>a+c.count,0);\n    document.getElementById('vault-meta').textContent = fmt(totalCases) + ' total opened';\n    vaultEl.innerHTML = data.cases\n      .sort((a,b)=>b.count-a.count)\n      .map(c => `\n        <div class=\"crate-card\">\n          <div class=\"crate-icon-box\">${crateIcon(c.accent)}</div>\n          <div class=\"crate-name\">${c.name}</div>\n          <div class=\"crate-count-row\">\n            <span class=\"crate-count\">${fmt(c.count)}</span>\n            <span class=\"crate-count-label\">opened</span>\n          </div>\n        </div>\n      `).join('');\n  } else {\n    document.getElementById('vault-meta').textContent = 'N/A — awaiting ingest';\n  }\n\n  // Rarity Breakdown\n  const ladderEl = document.getElementById('ladder');\n  if (data.rarity && data.rarity.length > 0) {\n    const totalItems = data.rarity.reduce((a,r)=>a+r.count,0);\n    document.getElementById('rarity-meta').textContent = fmt(totalItems) + ' items tracked';\n    const maxCount = Math.max(...data.rarity.map(r=>r.count)) || 1;\n    ladderEl.innerHTML = data.rarity.map(r => `\n      <div class=\"rung\">\n        <div class=\"rung-label\"><span class=\"rung-swatch\" style=\"background:${r.color}\"></span>${r.tier}</div>\n        <div class=\"rung-track\"><div class=\"rung-fill\" style=\"width:${(r.count/maxCount*100).toFixed(1)}%; background:${r.color}\"></div></div>\n        <div class=\"rung-count\"><b>${fmt(r.count)}</b></div>\n      </div>\n    `).join('');\n  } else {\n    document.getElementById('rarity-meta').textContent = 'N/A — awaiting ingest';\n  }\n}\n\nfunction tickClock(){\n  const now = new Date();\n  document.getElementById('sync-time').textContent = 'SYNCED ' + now.toTimeString().slice(0,8);\n}\n\nlet startTime = Date.now();\nfunction tickUptime(){\n  const diff = Date.now() - startTime;\n  const h = String(Math.floor(diff/3600000)).padStart(2,'0');\n  const m = String(Math.floor((diff%3600000)/60000)).padStart(2,'0');\n  const s = String(Math.floor((diff%60000)/1000)).padStart(2,'0');\n  document.getElementById('uptime-tick').textContent = `UPTIME ${h}:${m}:${s}`;\n}\n\n/* ============================================================\n   TAB SWITCHING LOGIC\n   ============================================================ */\nfunction switchTab(tabId){\n  const btnLive = document.getElementById('tab-btn-live');\n  const btnAbout = document.getElementById('tab-btn-about');\n  const paneLive = document.getElementById('pane-live');\n  const paneAbout = document.getElementById('pane-about');\n\n  if(tabId === 'about'){\n    btnLive.classList.remove('active');\n    btnLive.setAttribute('aria-selected', 'false');\n    btnAbout.classList.add('active');\n    btnAbout.setAttribute('aria-selected', 'true');\n    paneLive.classList.remove('active');\n    paneAbout.classList.add('active');\n    if(!window.location.hash.startsWith('#showcase')){\n      history.replaceState(null, '', '#about');\n    }\n  } else {\n    btnAbout.classList.remove('active');\n    btnAbout.setAttribute('aria-selected', 'false');\n    btnLive.classList.add('active');\n    btnLive.setAttribute('aria-selected', 'true');\n    paneAbout.classList.remove('active');\n    paneLive.classList.add('active');\n    history.replaceState(null, '', '#live');\n  }\n}\n\nfunction scrollToModule(targetId){\n  switchTab('about');\n  setTimeout(() => {\n    const el = document.getElementById(targetId);\n    if(el){\n      el.scrollIntoView({ behavior: 'smooth', block: 'start' });\n      history.replaceState(null, '', '#' + targetId);\n    }\n  }, 60);\n}\n\n/* ============================================================\n   LIGHTBOX MODAL & GALLERY\n   ============================================================ */\nconst SHOWCASE_ITEMS = [\n  {\n    title: \"01 // MASTER NODE & OPERATIONS DASHBOARD\",\n    src: \"/assets/01-master-node-dashboard.png\",\n    caption: \"BeaverOps Master Node desktop app: worker node orchestration, active slots, auto-farm toggle, and global database readout.\"\n  },\n  {\n    title: \"02 // COLLECT DROPS HARVEST MODULE\",\n    src: \"/assets/02-collect-drops.png\",\n    caption: \"BeaverOps internal drop harvester: multi-account inventory scanning, smart case/skin selection, and irreversible claim confirmation.\"\n  },\n  {\n    title: \"03 // WINDOWS FARM WORKER NODE (STABLE PRODUCTION)\",\n    src: \"/assets/03-windows-worker-node.png\",\n    caption: \"Windows production worker node: custom mutex isolation (kill_mutants.exe), named pipe IPC (cs2_farm), Smart Grid window pinning, and bot pathing overlay.\"\n  },\n  {\n    title: \"03-B // HEADLESS LINUX CLUSTER (EXPERIMENTAL BRANCH)\",\n    src: \"/assets/03-cs2-instances-htop.png\",\n    caption: \"Experimental Linux setup: 3 concurrent CS2 game sessions in Docker containers via docker-steam-headless, streamed via noVNC with htop monitoring.\"\n  },\n  {\n    title: \"04 // BEAVERTRADER LIQUIDATION & TRADING PANEL\",\n    src: \"/assets/04-trade-panel.png\",\n    caption: \"Automated trading console: Steam Desktop Authenticator (SDA) 2FA integration, SOCKS5 proxy rotation, and instant offer auto-confirm.\"\n  }\n];\n\nlet currentLightboxIdx = 0;\n\nfunction openLightbox(index){\n  currentLightboxIdx = index;\n  updateLightbox();\n  const modal = document.getElementById('lightbox-modal');\n  modal.classList.add('open');\n  document.body.style.overflow = 'hidden';\n}\n\nfunction closeLightbox(){\n  const modal = document.getElementById('lightbox-modal');\n  modal.classList.remove('open');\n  document.body.style.overflow = '';\n}\n\nfunction onLightboxBackdropClick(event){\n  if(event.target.id === 'lightbox-modal'){\n    closeLightbox();\n  }\n}\n\nfunction nextLightbox(){\n  currentLightboxIdx = (currentLightboxIdx + 1) % SHOWCASE_ITEMS.length;\n  updateLightbox();\n}\n\nfunction prevLightbox(){\n  currentLightboxIdx = (currentLightboxIdx - 1 + SHOWCASE_ITEMS.length) % SHOWCASE_ITEMS.length;\n  updateLightbox();\n}\n\nfunction updateLightbox(){\n  const item = SHOWCASE_ITEMS[currentLightboxIdx];\n  document.getElementById('lightbox-title').textContent = item.title;\n  document.getElementById('lightbox-counter').textContent = `[ ${currentLightboxIdx + 1} / ${SHOWCASE_ITEMS.length} ]`;\n  document.getElementById('lightbox-caption').textContent = item.caption;\n  const img = document.getElementById('lightbox-img');\n  img.src = item.src;\n  img.alt = item.title;\n}\n\nfunction setWorkerMode(mode){\n  const btnWin = document.getElementById('btn-worker-win');\n  const btnLinux = document.getElementById('btn-worker-linux');\n  const viewWin = document.getElementById('worker-view-win');\n  const viewLinux = document.getElementById('worker-view-linux');\n  const title = document.getElementById('worker-title');\n  const badge = document.getElementById('worker-status-badge');\n  const tag1 = document.getElementById('worker-tag-1');\n  const tag2 = document.getElementById('worker-tag-2');\n  const tag3 = document.getElementById('worker-tag-3');\n\n  if(mode === 'linux'){\n    btnWin.classList.remove('active');\n    btnLinux.classList.add('active');\n    viewWin.style.display = 'none';\n    viewLinux.style.display = 'grid';\n    title.textContent = 'Headless Multi-Instance CS2 Cluster (Experimental)';\n    badge.textContent = 'EXPERIMENTAL';\n    badge.classList.remove('highlight');\n    tag1.textContent = 'DOCKER CONTAINERS';\n    tag2.textContent = 'NOVNC STREAMING';\n    tag3.textContent = 'HTOP MONITORING';\n  } else {\n    btnLinux.classList.remove('active');\n    btnWin.classList.add('active');\n    viewLinux.style.display = 'none';\n    viewWin.style.display = 'grid';\n    title.textContent = 'Windows Farm Worker Node (Stable)';\n    badge.textContent = 'STABLE PRODUCTION';\n    badge.classList.add('highlight');\n    tag1.textContent = 'INTERNAL IPC cs2_farm';\n    tag2.textContent = 'SMART GRID HARD PIN';\n    tag3.textContent = 'MUTEX ISOLATION';\n  }\n}\n\nwindow.addEventListener('keydown', (e) => {\n  const modal = document.getElementById('lightbox-modal');\n  if(!modal.classList.contains('open')) return;\n  if(e.key === 'Escape') closeLightbox();\n  if(e.key === 'ArrowRight') nextLightbox();\n  if(e.key === 'ArrowLeft') prevLightbox();\n});\n\nwindow.addEventListener('DOMContentLoaded', () => {\n  const hash = window.location.hash;\n  if(hash === '#live'){\n    switchTab('live');\n  } else if(hash === '#about'){\n    switchTab('about');\n  } else if(hash.startsWith('#showcase')){\n    const targetId = hash.slice(1);\n    scrollToModule(targetId);\n  }\n});\n\n(async function init(){\n  const data = await fetchStats();\n  render(data);\n  tickClock();\n  tickUptime();\n  setInterval(tickClock, 1000);\n  setInterval(tickUptime, 1000);\n  setInterval(async () => render(await fetchStats()), 5 * 60 * 1000);\n})();\n\t</script>")
